fn find_prefix<'a>(items: &'a [String], prefix: &str) -> Option<&'a str> {
    for item in items {
        if item.starts_with(prefix) {
            return Some(item.as_str());
        }
    }
    None
}

fn find_prefix<'a>(items: &'a [String], prefix: &str) -> Option<&'a str> {
    for item in items {
        if item.starts_with(prefix) {
            let cloned = item.clone();
            return Some(cloned.as_str());
        }
    }
    None
}

fn find_prefix<'a>(items: &'a [String], prefix: &str) -> Option<&'a str> {
    for item in items {
        let s = item.to_string();
        if s.starts_with(prefix) {
            return Some(&s);
        }
    }
    None
}

